                                            anchors.rightMargin: 4
                                            text: root.itemTitle(timedChip.modelData)
                                            // R079: was AppTheme.text (grey). The ref's ink is
                                            // the chip's own calendar colour at half value.
                                            color: timedChip.inkColor
                                            font.pixelSize: 9

